class Solution:
    def countVowels(self, word: str) -> int:
        ans = 0
        n = len(word)
        for i in range(n):
            cnt = 0
            for j in range(i, n):
                if word[j] in "aeiou":
                    cnt += 1
                ans += cnt
        return ans

