class Solution {
public:
    long long countVowels(string word) {
        long long ans = 0;
        int n = word.size();
        for (int i = 0; i < n; i++) {
            long long cnt = 0;
            for (int j = i; j < n; j++) {
                char c = word[j];
                if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') cnt++;
                ans += cnt;
            }
        }
        return ans;
    }
};

